public class Partial_with_TriageGen0Test {

    @Test
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial();
        try {
            partial.with(null, 10);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The field type must not be null", e.getMessage());
        }
    }

    @Test
    public void testWith_ExistingField_DifferentValue_ReturnsNewPartial() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeZone.UTC);
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear(DateTimeZone.UTC);

        int[] types = {yearType.getDurationType().getField(DateTimeZone.UTC).getRangeDurationType().getField(DateTimeZone.UTC) != null ? 0 : 0}; // Dummy logic to satisfy types
        // Using constructor to build a partial with Year = 2020
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, DateTimeZone.UTC.getChronology());

        int newValue = 2021;
        Partial updated = partial.with(yearType, newValue);

        assertNotSame("Should return a new instance when value changes", partial, updated);
        assertEquals("New value should be updated", newValue, updated.getValue(0));
        assertEquals("Old value should remain unchanged in original", 2020, partial.getValue(0));
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeZone.UTC);
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, DateTimeZone.UTC.getChronology());

        Partial updated = partial.with(yearType, 2020);

        assertSame("Should return the same instance when value is identical", partial, updated);
    }

