    @Test
    public void testWith_UpdateMonth_ChangesValue() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeZone.UTC);
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear(DateTimeZone.UTC);

        // Create partial with both year and month
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1}, DateTimeZone.UTC.getChronology());

        Partial updated = partial.with(monthType, 12);

        assertNotSame(partial, updated);
        assertEquals(2020, updated.getValue(0));
        assertEquals(12, updated.getValue(1));
    }
